// Data source.
//
//   VITE_DATA_MODE=api    (default) — call the FastAPI backend via the Vite
//                                     dev proxy. Used for local development.
//   VITE_DATA_MODE=static           — read pre-rendered JSON from /api/*.json,
//                                     generated by scripts/export_static.py and
//                                     copied out of public/ by Vite. This is
//                                     what the deployed site uses.
//
// Both modes expose the same functions and the same response shapes, so no
// component needs to know which is active.
const DATA_MODE = import.meta.env.VITE_DATA_MODE || 'api'
// In static mode, Vite's base is /health-dashboard/ (set in vite.config.js),
// so API_BASE becomes /health-dashboard/api. In dev mode base is '/', so
// API_BASE stays /api. This keeps fetch URLs correct in both modes.
const API_BASE = import.meta.env.BASE_URL + 'api'

export const IS_STATIC = DATA_MODE === 'static'

// Query parameters the exporter bakes in as the default. A static build has
// exactly one file per path, so a request carrying these is served that file;
// any *other* parameter would need a variant that does not exist.
const STATIC_DEFAULTS = new Set(['sex=SEX_BTSX'])

function staticUrl(path, params) {
  // URLSearchParams iterates as [key, value] pairs; normalise to "k=v" strings.
  const kept = params ? [...params].map(([k, v]) => `${k}=${v}`).filter((p) => !STATIC_DEFAULTS.has(p)) : []
  if (kept.length) {
    // Fail loudly rather than silently returning the default variant, which
    // would show wrong numbers for the requested slice.
    throw new Error(
      `Static build has no pre-rendered data for ${path}?${kept.join('&')}. ` +
        `Re-run scripts/export_static.py to generate it.`,
    )
  }
  return `${API_BASE}${path}.json`
}

async function fetchJSON(path, params) {
  const hasParams = params ? [...params].length > 0 : false
  const url = IS_STATIC
    ? staticUrl(path, params)
    : `${API_BASE}${path}${hasParams ? `?${params}` : ''}`

  const resp = await fetch(url)
  if (!resp.ok) {
    throw new Error(`API error: ${resp.status} ${resp.statusText}`)
  }
  return resp.json()
}

// Sex dimension in the data.
//
// The two upstream APIs disagree on how they express "both sexes":
//   - WHO GHO sex-disaggregated indicators (life expectancy, U5MR, HIV, NCD,
//     suicide, tobacco, obesity) send Dim1 = 'SEX_BTSX'.
//   - Indicators with no sex dimension at all (MMR, UHC index, TB, malaria,
//     population, GDP, beds, physicians, expenditure, water, sanitation)
//     come back with sex = null.
//
// Filtering on 'SEX_BTSX' alone therefore silently drops every null-sex
// indicator and renders those charts and stat cards empty. No indicator in
// this dataset has both forms, so accepting either cannot duplicate years.
export const SEX_BOTH = 'SEX_BTSX'

export function isBothSexes(row) {
  // == null covers both null and undefined.
  return row.sex === SEX_BOTH || row.sex == null
}

/** Keep both-sexes rows only, oldest year first. */
export function bothSexesSeries(rows) {
  return (rows ?? [])
    .filter(isBothSexes)
    .sort((a, b) => a.year - b.year)
}

export async function getIndicators(category, source) {
  const params = new URLSearchParams()
  if (category) params.set('category', category)
  if (source) params.set('source', source)
  return fetchJSON('/indicators', params)
}

export async function getIndicatorData(indicatorCode, year, region) {
  const params = new URLSearchParams()
  if (year) params.set('year', year)
  if (region) params.set('region', region)
  return fetchJSON(`/data/${indicatorCode}`, params)
}

// Wealth-quintile breakdown (Q1 poorest .. Q5 richest + national total).
// Throws on 404 when the indicator has no quintile disaggregation.
export async function getIndicatorQuintiles(indicatorCode, { sex, yearFrom, yearTo } = {}) {
  const params = new URLSearchParams()
  if (sex) params.set('sex', sex)
  if (yearFrom) params.set('year_from', yearFrom)
  if (yearTo) params.set('year_to', yearTo)
  return fetchJSON(`/data/${indicatorCode}/quintiles`, params)
}

export async function getCategories() {
  return fetchJSON('/categories')
}

// Plain-language metric descriptions, keyed by indicator code. Static per
// deploy, so fetch once and cache in module scope — every chart asks for this.
let metricInfoPromise = null
export function getMetricInfo() {
  if (!metricInfoPromise) {
    metricInfoPromise = fetchJSON('/metric-info').catch((e) => {
      // A missing blurb must never break a chart.
      console.warn('metric-info unavailable:', e.message)
      metricInfoPromise = null
      return {}
    })
  }
  return metricInfoPromise
}

export async function getSources() {
  return fetchJSON('/sources')
}

// Only meaningful in api mode; the static build has no live backend to probe.
export async function getHealth() {
  if (IS_STATIC) return { status: 'static' }
  return fetchJSON('/health')
}
